// @name Memory match
// @background #f1eee6
// @refresh 3600
// Memory for a touch screen: tap two cards to turn them over; a pair stays
// up, two that differ turn back with your next tap (no timers, so it plays
// the same on e-paper). Alone, beat your fewest moves for each size; with
// two players, a pair found keeps the turn.
import { ICONS, ICON_COLORS } from './icons'
import { highContrast, canvasOf, Button, OptionsPage, Title, roundRoom } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f1eee6] text-[#22303a]',
    muted: 'text-[#5f6a72]',
    button: 'bg-[#e1dccf] text-[#22303a] active:bg-[#d2cbba]',
    primary: 'bg-[#2c5f6e] text-white active:bg-[#3a7586]',
    on: 'bg-[#2c5f6e] text-white',
    off: 'bg-[#e1dccf] text-[#22303a]',
    turn: 'bg-[#2c5f6e] text-white',
    idle: 'text-[#22303a]',
    back: '#2c5f6e',
    backLine: '#3f7787',
    backEdge: '#21495a',
    face: '#fffdf8',
    faceEdge: '#c9c2b2',
    upEdge: '#d9962b',
    done: '#e7e2d6',
    doneEdge: '#d6cfbf',
    mono: '',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    turn: 'bg-black text-white',
    idle: 'text-black border-2 border-black',
    back: '#000000',
    backLine: '#ffffff',
    backEdge: '#000000',
    face: '#ffffff',
    faceEdge: '#000000',
    upEdge: '#000000',
    done: '#ffffff',
    doneEdge: '#000000',
    mono: '#000000',
  },
}

// Board sizes as columns x rows on a wide screen (turned on a tall one).
const SIZES = { '4x3': [4, 3], '4x4': [4, 4], '6x4': [6, 4], '6x5': [6, 5] }

const settingsOf = (app) => ({
  size: SIZES[app.state.size] ? app.state.size : '4x4',
  players: app.state.players === '2' || app.state.players === 2 ? 2 : 1,
})

// The game in progress, kept in the scene's private `game` field:
//   deck     the picture on each card (two cards each)
//   owner    one character a card: "0" still hidden, "1" / "2" the player
//            who found its pair
//   up       the one or two cards turned over and not yet a pair
//   last     the pair found last (drawn ringed), turn, moves, scores
type Game = {
  size: string
  players: number
  deck: number[]
  owner: string
  up: number[]
  last: number[]
  turn: number
  moves: number
  scores: number[]
}

const shuffle = (pairs: number): number[] => {
  // Which pictures, then where: both at random.
  const pictures = ICONS.map((_, i) => i)
  for (let i = pictures.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[pictures[i], pictures[j]] = [pictures[j], pictures[i]]
  }
  const deck: number[] = []
  for (let i = 0; i < pairs; i++) deck.push(pictures[i], pictures[i])
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[deck[i], deck[j]] = [deck[j], deck[i]]
  }
  return deck
}

const newGame = (app): Game => {
  const { size, players } = settingsOf(app)
  const [c, r] = SIZES[size]
  return { size, players, deck: shuffle((c * r) / 2), owner: '0'.repeat(c * r), up: [], last: [], turn: 1, moves: 0, scores: [0, 0] }
}

// What a tap changes is signals: each card's look, the status and the scores.
// A tap runs only the components that read them, not get().
const cardLooks = Array.from({ length: 30 }, () => signal('down'))
const info = signal({ headline: '', detail: '', scores: [0, 0], turn: 1, done: false })
// The game get() last loaded (a tap plays on it) and the best for its size.
let game: Game | null = null
let best = 0

const loadGame = (app): Game | null => {
  const g = app.state.game
  return g && Array.isArray(g.deck) && typeof g.owner === 'string' && g.owner.length === g.deck.length ? g : null
}
const save = (game: Game) => frameos.setState('game', game)

const finished = (game: Game) => game.owner.indexOf('0') < 0

const bestOf = (app, size: string) => (app.state.best && typeof app.state.best === 'object' ? app.state.best[size] : 0)

// The signals from the game: each card's look, the status line and the
// scores. A signal set to what it holds already wakes nothing.
const show = (s, value) => {
  if (JSON.stringify(s.peek()) !== JSON.stringify(value)) s.value = value
}
const sync = (game: Game) => {
  const done = finished(game)
  for (let i = 0; i < game.deck.length; i++) {
    show(cardLooks[i], game.up.includes(i) ? 'up'
      : game.owner[i] === '0' ? 'down'
      : game.last.includes(i) && !done ? 'last'
      : 'done')
  }
  const pairs = game.deck.length / 2
  let headline = ''
  let detail = ''
  if (game.players === 1) {
    headline = `${game.moves} ${game.moves === 1 ? 'move' : 'moves'}`
    if (done) detail = frameos.recall('record') ? 'All pairs found, a new best!' : best ? `All pairs found. Best: ${best}` : 'All pairs found'
    else detail = `${game.scores[0]} of ${pairs} pairs${best ? ` · best ${best}` : ''}`
  } else if (done) {
    const [a, b] = game.scores
    headline = a === b ? 'A tie!' : `Player ${a > b ? 1 : 2} wins!`
    detail = `${Math.max(a, b)} pairs to ${Math.min(a, b)}`
  } else {
    headline = `Player ${game.turn}'s turn`
    detail = game.up.length === 2 ? 'No pair. Tap to go on' : 'Find a pair'
  }
  if (game.players === 1 && !done && game.up.length === 2) detail = 'No pair. Tap to go on'
  show(info, { headline, detail, scores: game.scores.slice(), turn: game.turn, done })
}

// A tap on card `i`.
const tapCard = (app, i: number) => {
  if (!game || i < 0 || i >= game.deck.length || finished(game)) return
  // Two that did not match turn back first; the tap also turns the card it
  // landed on, unless it was one of those two.
  if (game.up.length === 2) {
    const wasUp = game.up.includes(i)
    game.up = []
    if (wasUp) {
      save(game)
      sync(game)
      return
    }
  }
  if (game.owner[i] !== '0' || game.up.includes(i)) {
    save(game)
    sync(game)
    return
  }
  game.up = [...game.up, i]
  if (game.up.length === 2) {
    game.moves++
    const [a, b] = game.up
    if (game.deck[a] === game.deck[b]) {
      const mark = String(game.turn)
      game.owner = game.owner.split('').map((o, k) => (k === a || k === b ? mark : o)).join('')
      game.scores = game.scores.map((s, k) => (k === game.turn - 1 ? s + 1 : s))
      game.last = [a, b]
      game.up = []
      if (finished(game)) recordBest(app, game)
    } else if (game.players === 2) {
      game.turn = 3 - game.turn
    }
  }
  save(game)
  sync(game)
}

const recordBest = (app, game: Game) => {
  if (game.players !== 1) return
  const all = app.state.best && typeof app.state.best === 'object' ? { ...app.state.best } : {}
  frameos.remember('record', !all[game.size] || game.moves < all[game.size])
  if (!all[game.size] || game.moves < all[game.size]) {
    all[game.size] = game.moves
    frameos.setState('best', all)
  }
  best = all[game.size]
}

const restart = (app) => {
  save(newGame(app))
  frameos.remember('page', null)
}

// Frames with buttons: forward deals a new game once this one is done.
export function onEvent(app, context) {
  if (context.event !== 'forward') return false
  const game = loadGame(app)
  if (game && !finished(game)) return false
  restart(app)
  return true
}

const Card = memo(({ t, i, x, y, w, h, picture }) => {
  const state = cardLooks[i].value
  const r = Math.min(w, h) * 0.1
  if (state === 'down') {
    // The back: a frame and a small diamond in the middle.
    const inset = Math.min(w, h) * 0.12
    const d = Math.min(w, h) * 0.16
    return (
      <g>
        <rect x={x} y={y} width={w} height={h} rx={r} fill={t.back} stroke={t.backEdge} strokeWidth={2} />
        <rect x={x + inset} y={y + inset} width={w - inset * 2} height={h - inset * 2} fill="none" stroke={t.backLine} strokeWidth={Math.max(2, Math.min(w, h) * 0.03)} />
        <polygon points={`${x + w / 2},${y + h / 2 - d} ${x + w / 2 + d},${y + h / 2} ${x + w / 2},${y + h / 2 + d} ${x + w / 2 - d},${y + h / 2}`} fill={t.backLine} />
      </g>
    )
  }
  const s = (Math.min(w, h) * (state === 'done' ? 0.56 : 0.66)) / 100
  const color = t.mono || ICON_COLORS[picture % ICON_COLORS.length]
  const edge = state === 'up' || state === 'last' ? t.upEdge : state === 'done' ? t.doneEdge : t.faceEdge
  const width = state === 'up' || state === 'last' ? Math.max(3, Math.round(Math.min(w, h) * 0.06)) : 2
  // The frame is a rounded rectangle under the face, not a stroke: a thick
  // stroke's corners join unevenly.
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx={r} fill={edge} />
      <rect x={x + width} y={y + width} width={w - width * 2} height={h - width * 2} rx={Math.max(1, r - width)} fill={state === 'done' ? t.done : t.face} />
      <g transform={`translate(${x + w / 2 - 50 * s} ${y + h / 2 - 50 * s}) scale(${s})`}>{ICONS[picture](color)}</g>
    </g>
  )
})

// The moves or whose turn it is, over what to do next.
const Status = memo(({ ui, t }) => {
  const { headline, detail } = info.value
  return (
    <div className="flex flex-col">
      <span className={`text-[${ui.big}px] font-bold leading-tight`}>{headline}</span>
      <span className={`text-[${ui.small}px] ${t.muted}`}>{detail}</span>
    </div>
  )
})

// Two players' pairs, the one whose turn it is lit.
const ScoreChips = memo(({ ui, t }) => {
  const { scores, turn, done } = info.value
  return (
    <div className={`flex gap-[${Math.round(ui.gap * 0.6)}px]`}>
      {[1, 2].map((p) => (
        <div className={`flex-1 basis-0 rounded-xl px-[${ui.gap}px] py-[${Math.round(ui.gap * 0.5)}px] flex flex-col items-center ${!done && turn === p ? t.turn : t.idle}`}>
          <span className={`text-[${ui.small}px]`}>{`Player ${p}`}</span>
          <span className={`text-[${ui.big}px] font-bold leading-tight`}>{String(scores[p - 1])}</span>
        </div>
      ))}
    </div>
  )
})

// New game, lit once the game is done.
const NewButton = memo(({ ui, t, grow, onClick }) => (
  <Button ui={ui} grow={grow} className={info.value.done ? t.primary : t.button} onClick={onClick}>New game</Button>
))

// On a round panel: the moves or whose turn it is, centred in the arc above the cards.
const RoundStatus = memo(({ size, small, t }) => {
  const { headline, detail } = info.value
  return (
    <div className="flex flex-col items-center">
      <span className={`text-[${size}px] font-bold leading-tight`}>{headline}</span>
      <span className={`text-[${small}px] ${t.muted}`}>{detail}</span>
    </div>
  )
})
// One player's pairs, in the arc beside the cards; lit on their turn.
const RoundChip = memo(({ p, w, size, small, t }) => {
  const { scores, turn, done } = info.value
  return (
    <div className={`w-[${w}px] rounded-xl py-[6px] flex flex-col items-center ${!done && turn === p ? t.turn : t.idle}`}>
      <span className={`text-[${small}px]`}>{`P${p}`}</span>
      <span className={`text-[${size}px] font-bold leading-tight`}>{String(scores[p - 1])}</span>
    </div>
  )
})
const RoundNew = memo(({ w, h, size, t }) => (
  <div className={`w-[${w}px] h-[${h}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${size}px] font-semibold ${info.value.done ? t.primary : t.button}`}
    onClick={restartLast}>
    New game
  </div>
))

// The sizes kept as one object while they stay the same, and the app get()
// last ran with: what the memo()'d components are given stays equal.
let steady = null
const steadyUi = (ui) => (steady && Object.keys(ui).every((key) => ui[key] === steady[key]) ? steady : (steady = ui))
let lastApp = null
const restartLast = () => restart(lastApp)

export function get(app, context) {
  lastApp = app
  const ui = steadyUi(canvasOf(app, context))
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const settings = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows = [
      { field: 'size', label: 'Cards', value: settings.size, options: [['4x3', '12'], ['4x4', '16'], ['6x4', '24'], ['6x5', '30']] },
      { field: 'players', label: 'Players', value: String(settings.players), options: [['1', 'One'], ['2', 'Two']] },
    ]
    return <OptionsPage ui={ui} t={t} title="Memory match" rows={rows}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  game = loadGame(app)
  if (!game || game.size !== settings.size || game.players !== settings.players) {
    game = newGame(app)
    save(game)
  }
  best = bestOf(app, game.size)
  sync(game)

  // Round: the cards in the square inside the circle, the status in the arc
  // above, two players' pairs in the arcs beside, the buttons in the arc below.
  const room = ui.round ? roundRoom(ui.W, ui.H) : null
  // Side by side on a wide screen, stacked on a tall or square one; the
  // cards turn with the screen.
  const side = !room && ui.W >= ui.H * 1.15
  const tall = !room && ui.H > ui.W * 1.1
  const [c0, r0] = SIZES[game.size]
  const cols = tall ? r0 : c0
  const rows = tall ? c0 : r0
  const sideW = Math.round(Math.max(ui.W * 0.25, ui.text * 9))
  const areaW = room ? room.side : side ? ui.W - sideW - ui.pad * 3 : ui.W - ui.pad * 2
  const areaH = room ? room.side - Math.round(ui.button * 0.5) : side ? ui.H - ui.pad * 2 : ui.H - ui.pad * 2 - (ui.gap + ui.button) * 2
  const gap = Math.max(4, Math.round(Math.min(areaW / cols, areaH / rows) * 0.07))
  let w = (areaW - gap * (cols - 1)) / cols
  let h = (areaH - gap * (rows - 1)) / rows
  // Cards keep a card's shape: between square and 3:4.
  if (w > h) w = h
  if (h > w * 1.35) h = w * 1.35
  w = Math.floor(w)
  h = Math.floor(h)
  const boardW = cols * w + (cols - 1) * gap
  const boardH = rows * h + (rows - 1) * gap

  const cards = []
  for (let i = 0; i < game.deck.length; i++) {
    const col = i % cols
    const row = Math.floor(i / cols)
    cards.push(<Card t={t} i={i} x={col * (w + gap)} y={row * (h + gap)} w={w} h={h} picture={game.deck[i]} />)
  }
  const board = (
    <div className={`w-[${boardW}px] h-[${boardH}px] shrink-0`}
      onClick={(e) => {
        const col = Math.floor(e.localX / (w + gap))
        const row = Math.floor(e.localY / (h + gap))
        if (col >= 0 && col < cols && row >= 0 && row < rows) tapCard(app, row * cols + col)
      }}>
      <svg viewBox={`-2 -2 ${boardW + 4} ${boardH + 4}`} width={boardW} height={boardH}>{cards}</svg>
    </div>
  )

  if (room) {
    const { chord } = room
    const top = (ui.H - boardH) >> 1
    const size = Math.max(16, Math.min(ui.big, Math.round(top * 0.26)))
    const small = Math.max(14, Math.min(ui.small, size - 4))
    const bh = Math.max(40, Math.min(ui.button, Math.round(top * 0.55)))
    const bTop = top + boardH + Math.max(6, Math.round(top * 0.08))
    const bw = Math.floor((chord(bTop + bh - ui.H / 2) - ui.gap) / 2)
    const bFont = Math.max(14, Math.min(ui.text, Math.round(bh * 0.42), Math.round(bw / 5.4)))
    const besideW = (ui.W - boardW) >> 1
    const chip = (p: number) => (
      <div className={`absolute ${p === 1 ? 'left-0 pl-[14px]' : 'right-0 pr-[14px]'} top-0 w-[${besideW}px] h-[${ui.H}px] flex items-center justify-center`}>
        <RoundChip p={p} w={Math.max(36, besideW - 28)} size={size} small={small} t={t} />
      </div>
    )
    return (
      <div className={`relative w-[${ui.W}px] h-[${ui.H}px] ${t.page}`}>
        <div className={`absolute left-0 top-0 w-[${ui.W}px] h-[${top - 6}px] flex items-end justify-center`}>
          <RoundStatus size={size} small={small} t={t} />
        </div>
        {game.players === 2 ? chip(1) : null}
        {game.players === 2 ? chip(2) : null}
        <div className={`absolute left-[${(ui.W - boardW) >> 1}px] top-[${top}px]`}>{board}</div>
        <div className={`absolute left-0 top-[${bTop}px] w-[${ui.W}px] flex justify-center gap-[${ui.gap}px]`}>
          <RoundNew w={bw} h={bh} size={bFont} t={t} />
          <div className={`w-[${bw}px] h-[${bh}px] rounded-xl flex items-center justify-center text-[${bFont}px] font-semibold ${t.button}`}
            onClick={() => frameos.remember('page', 'options')}>
            Options
          </div>
        </div>
      </div>
    )
  }

  const scoreChips = game.players === 2 ? <ScoreChips ui={ui} t={t} /> : null
  const status = <Status ui={ui} t={t} />
  const newButton = <NewButton ui={ui} t={t} grow={!side} onClick={restartLast} />
  const optionsButton = <Button ui={ui} grow={!side} className={t.button} onClick={() => frameos.remember('page', 'options')}>Options</Button>

  if (side) {
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        <div className="flex-1 h-full flex items-center justify-center">{board}</div>
        <div className={`w-[${sideW}px] h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={sideW}>Memory</Title>
          {status}
          <div className="flex-1" />
          {scoreChips}
          <div className={`space-y-[${ui.gap}px]`}>
            {newButton}
            {optionsButton}
          </div>
        </div>
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
      <div className={`flex items-center justify-between gap-[${ui.gap}px] h-[${ui.button}px]`}>
        {status}
        {scoreChips}
      </div>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <div className={`flex gap-[${ui.gap}px]`}>
        {newButton}
        {optionsButton}
      </div>
    </div>
  )
}

