// The pictures on the cards, each drawn in a 100x100 box from plain shapes
// (text has no emoji on a frame). `c` is the fill.

const starPoints = (cx: number, cy: number, outer: number, inner: number, points: number) => {
  const out: string[] = []
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 ? inner : outer
    const a = (Math.PI * i) / points - Math.PI / 2
    out.push(`${Math.round((cx + Math.cos(a) * r) * 10) / 10},${Math.round((cy + Math.sin(a) * r) * 10) / 10}`)
  }
  return out.join(' ')
}

const sunRays = (c: string) => {
  const rays = []
  for (let i = 0; i < 8; i++) {
    const a = (Math.PI * i) / 4
    rays.push(
      <line x1={50 + Math.cos(a) * 30} y1={50 + Math.sin(a) * 30} x2={50 + Math.cos(a) * 44} y2={50 + Math.sin(a) * 44}
        stroke={c} strokeWidth={8} strokeLinecap="round" />,
    )
  }
  return rays
}

export const ICONS = [
  // sun
  (c: string) => <g><circle cx={50} cy={50} r={20} fill={c} />{sunRays(c)}</g>,
  // heart
  (c: string) => <path d="M50 86 C20 64 8 48 8 32 C8 18 19 9 31 9 C40 9 46 14 50 21 C54 14 60 9 69 9 C81 9 92 18 92 32 C92 48 80 64 50 86 Z" fill={c} />,
  // star
  (c: string) => <polygon points={starPoints(50, 54, 44, 18, 5)} fill={c} />,
  // moon
  (c: string) => <path d="M62 8 A42 42 0 1 0 92 70 A34 34 0 1 1 62 8 Z" fill={c} />,
  // mountains
  (c: string) => <g><polygon points="4,86 38,26 72,86" fill={c} /><polygon points="46,86 70,46 96,86" fill={c} /></g>,
  // crown
  (c: string) => <g><polygon points="8,78 8,28 30,50 50,14 70,50 92,28 92,78" fill={c} /><rect x={8} y={82} width={84} height={10} fill={c} /></g>,
  // drop
  (c: string) => <path d="M50 6 C62 28 80 44 80 64 C80 82 66 94 50 94 C34 94 20 82 20 64 C20 44 38 28 50 6 Z" fill={c} />,
  // leaf
  (c: string) => <g><path d="M14 86 C10 40 40 12 90 10 C88 60 60 90 14 86 Z" fill={c} /><line x1={14} y1={86} x2={58} y2={42} stroke="#ffffff" strokeWidth={5} strokeLinecap="round" /></g>,
  // house
  (c: string) => <g><polygon points="50,8 92,46 82,46 82,90 18,90 18,46 8,46" fill={c} /><rect x={42} y={62} width={16} height={28} fill="#ffffff" /></g>,
  // lightning bolt
  (c: string) => <polygon points="58,4 18,56 46,56 38,96 82,40 54,40 64,4" fill={c} />,
  // ring
  (c: string) => <circle cx={50} cy={50} r={33} fill="none" stroke={c} strokeWidth={15} />,
  // hexagon
  (c: string) => <polygon points="50,6 88,28 88,72 50,94 12,72 12,28" fill={c} />,
  // tree
  (c: string) => <g><polygon points="50,4 86,64 14,64" fill={c} /><rect x={42} y={60} width={16} height={32} fill={c} /></g>,
  // fish
